/* ============ RENDER FUNCTIONS ============ */
function renderSyllabus(){
const grid = document.getElementById('syllabusGrid');
grid.innerHTML = Object.entries(syllabusData).map(([sem, subs])=>`
<div class="sem-card">
<h3><span class="sem-badge">SEM ${sem}</span> Semester ${sem}</h3>
<ul>${subs.map(s=>`<li><span class="li-icon">📘</span>${s.n}<span class="li-code">${s.c}</span></li>`).join('')}</ul>
</div>
`).join('');
}
function renderRoadmaps(){
const grid = document.getElementById('roadmapGrid');
grid.innerHTML = roadmapList.map(r=>`
<div class="roadmap-card">
<div class="rm-icon">${r.icon}</div>
<h3>${r.title}</h3>
<p>${r.desc}</p>
<a class="rm-link" href="${r.link}" target="_blank" rel="noopener">Open Roadmap →</a>
</div>
`).join('');
}
let currentSem = 1;
let currentSubject = null;
function renderNotesList(){
const view = document.getElementById('notesView');
const subjects = notesData[currentSem] || [];
view.innerHTML = `
<div class="section-head left">
<span class="eyebrow">Semester ${currentSem}</span>
<h2>Notes — Semester <em>${currentSem}</em></h2>
<p>${subjects.length} subjects · Click any subject to explore module-wise notes with YouTube lectures, GeeksforGeeks articles & roadmaps.</p>
</div>
<div class="notice-banner">
<span class="notice-icon">ℹ️</span>
<div><b>Notice:</b> Some modules or subjects might not have any notes on GeeksforGeeks webpage. In such cases, the GFG button will appear disabled. You can still learn from the YouTube lectures and roadmap.sh links provided for every module.</div>
</div>
<div class="sem-tabs">
${[1,2,3,4,5,6].map(s=>`<button class="sem-tab ${s===currentSem?'active':''}" onclick="selectSem(${s})">Sem ${s}</button>`).join('')}
</div>
<div class="subject-grid">
${subjects.map((s,i)=>`
<div class="subject-card" onclick="openSubject(${i})">
<span class="type-badge type-${getTypeClass(s.code)}">${getTypeBadge(s.code)}</span>
<div class="subject-icon">${s.icon}</div>
<h3>${s.name}</h3>
<div class="meta">
<span>📖 ${s.modules.length} Modules</span>
<span>🎬 ${s.modules.reduce((a,m)=>a+m.topics.length,0)} Topics</span>
</div>
<span class="tag">${s.code}</span>
</div>
`).join('')}
</div>
`;
}
function getTypeBadge(code){
const prefix = code.split('-')[0];
if(prefix==='CC') return 'Core';
if(prefix==='SEC') return 'Skill';
if(prefix==='DSE') return 'Elective';
if(prefix==='VAC') return 'Value';
if(prefix==='MDE') return 'Mandatory';
if(prefix==='AEC') return 'Ability';
if(prefix==='OE') return 'Open';
if(prefix==='AIML') return 'AI/ML';
if(prefix==='AP') return 'Aptitude';
return 'Core';
}
function getTypeClass(code){
const prefix = code.split('-')[0];
const map = {CC:'cc',SEC:'sec',DSE:'dse',VAC:'vac',MDE:'mde',AEC:'aec',OE:'oe',AIML:'aiml',AP:'ap'};
return map[prefix] || 'cc';
}
function selectSem(s){currentSem=s;currentSubject=null;renderNotesList()}
function openSubject(idx){currentSubject=notesData[currentSem][idx];renderSubjectDetail()}
function renderGfgButton(gfgLink){
if(gfgLink){
return `<a class="link-btn gfg" href="${gfgLink}" target="_blank" rel="noopener">📚 GeeksforGeeks</a>`;
}
return `<span class="link-btn na" title="GeeksforGeeks article not available for this module">📚 GFG Not Available</span>`;
}
function renderSubjectDetail(){
const s = currentSubject;
const view = document.getElementById('notesView');
view.innerHTML = `
<button class="back-btn" onclick="backToList()">← Back to Semester ${currentSem}</button>
<div class="subject-header">
<span class="icon-big">${s.icon}</span>
<span class="code-badge">${s.code}</span>
<h2>${s.name}</h2>
<p>${s.modules.length} Modules · Complete coverage with video lectures, GeeksforGeeks articles & roadmaps</p>
</div>
<div class="notice-banner">
<span class="notice-icon">ℹ️</span>
<div><b>Notice:</b> Some modules or subjects might not have any notes on GeeksforGeeks webpage. Wherever the GFG button shows as "Not Available", you can still rely on the YouTube lectures and roadmap.sh links for that module.</div>
</div>
<div class="module-list">
${s.modules.map((m,i)=>`
<div class="module">
<div class="module-head">
<div class="module-title">
<span class="module-num">${i+1}</span>
${m.title}
</div>
</div>
<div class="module-topics">
${m.topics.map(t=>`<span class="topic-chip">${t}</span>`).join('')}
</div>
<div class="module-links">
<a class="link-btn yt" href="${m.yt}" target="_blank" rel="noopener">▶️ YouTube</a>
${renderGfgButton(m.gfg)}
<a class="link-btn rm" href="${m.rm}" target="_blank" rel="noopener">🗺️ Roadmap.sh</a>
</div>
</div>
`).join('')}
</div>
`;
window.scrollTo({top:0,behavior:'smooth'});
}
function backToList(){currentSubject=null;renderNotesList()}
/* ============ NAVIGATION ============ */
function goTo(target){
document.querySelectorAll('.section').forEach(s=>s.classList.remove('active'));
document.getElementById(target).classList.add('active');
document.querySelectorAll('.nav-links button[data-target]').forEach(b=>{
b.classList.toggle('active', b.dataset.target===target);
});
document.getElementById('navLinks').classList.remove('open');
window.scrollTo({top:0,behavior:'smooth'});
}
document.querySelectorAll('.nav-links button[data-target]').forEach(btn=>{
btn.addEventListener('click',()=>goTo(btn.dataset.target));
});
document.getElementById('menuBtn').addEventListener('click',()=>{
document.getElementById('navLinks').classList.toggle('open');
});
/* ============ SEARCH WITH DEBOUNCE ============ */
let searchTimeout = null;
function performSearch(query){
const q = query.toLowerCase().trim();
if(!q){ goTo('home'); return; }
goTo('notes');
const matches = [];
Object.entries(notesData).forEach(([sem, subs])=>{
subs.forEach((s,idx)=>{
const hay = (s.name+' '+s.code+' '+s.modules.map(m=>m.title+' '+m.topics.join(' ')).join(' ')).toLowerCase();
if(hay.includes(q)) matches.push({sem:parseInt(sem),idx,subject:s});
});
});
const view = document.getElementById('notesView');
if(matches.length===0){
view.innerHTML = `
<div class="section-head left">
<span class="eyebrow">Search</span>
<h2>No results found for "<em>${q}</em>"</h2>
<p>Try searching for subjects like Data Structures, DBMS, Java, Cloud Computing, etc.</p>
</div>
<button class="back-btn" onclick="document.getElementById('globalSearch').value='';goTo('home')">← Clear Search</button>
`;
return;
}
view.innerHTML = `
<div class="section-head left">
<span class="eyebrow">Search Results</span>
<h2>Results for "<em>${q}</em>"</h2>
<p>${matches.length} match${matches.length>1?'es':''} found across all semesters.</p>
</div>
<button class="back-btn" onclick="document.getElementById('globalSearch').value='';goTo('home')">← Clear Search</button>
<div class="subject-grid">
${matches.map(m=>`
<div class="subject-card" onclick="currentSem=${m.sem};openSubject(${m.idx})">
<div class="subject-icon">${m.subject.icon}</div>
<h3>${m.subject.name}</h3>
<div class="meta"><span>Semester ${m.sem}</span><span>📖 ${m.subject.modules.length} Modules</span></div>
<span class="tag">${m.subject.code}</span>
</div>
`).join('')}
</div>
`;
}


// Search Changes every search on the webapge get controlled with this function
const searchInput = document.getElementById('globalSearch');
searchInput.addEventListener('input',(e)=>{
if(searchTimeout) clearTimeout(searchTimeout);
searchTimeout = setTimeout(()=>{
performSearch(e.target.value);
},500);
});
searchInput.addEventListener('keypress',(e)=>{
if(e.key==='Enter'){
if(searchTimeout) clearTimeout(searchTimeout);
performSearch(e.target.value);
}
});
/* ============ INIT ============ */
renderSyllabus();
renderRoadmaps();
renderNotesList();